int write_file_content(const char *filepath, FileContent *fc) {
    FILE *file = fopen(filepath, "w");
    if (!file) return -1;

    for (int i = 0; i < fc->sentence_count; i++) {
        for (int j = 0; j < fc->sentences[i].word_count; j++) {
            write_word_to_file(file, fc->sentences[i].words[j]);

            if (j < fc->sentences[i].word_count - 1) {
                const char* cur = fc->sentences[i].words[j];
                const char *next = (j + 1 < fc->sentences[i].word_count) ? 
                           fc->sentences[i].words[j + 1] : NULL;

                if (next) {
                    int cur_is_delim = is_delimiter(cur[0]);
                    int next_is_delim = is_delimiter(next[0]);
                    int cur_is_newline = (cur[0] == '\n' && cur[1] == '\0');
                    int next_is_newline = (next[0] == '\n' && next[1] == '\0');
                    int cur_is_space = is_space_token(cur);
                    int next_is_space = is_space_token(next);

                    if (cur_is_space || next_is_space || cur_is_newline || next_is_newline) {
                        continue;
                    }

                    if (cur_is_delim || next_is_delim) {
                        continue;
                    }

                    fprintf(file, " ");
                }
            }

            printf("DEBUG write token[%d][%d] = '%s' (is_space=%d)\n", i, j, fc->sentences[i].words[j], is_space_token(fc->sentences[i].words[j]));
        }

        /* Add space between sentences (except after last), but avoid
           inserting an extra space if the sentence already ends with a
           newline/space token or the next sentence already starts with one. */
        if (i < fc->sentence_count - 1) {
            int add_space = 1;

            if (fc->sentences[i].word_count > 0) {
                char *last = fc->sentences[i].words[fc->sentences[i].word_count - 1];
                if (is_newline_token(last) || is_space_token(last)) {
                    add_space = 0;
                }
            }

            if (fc->sentences[i+1].word_count > 0) {
                char *first_next = fc->sentences[i+1].words[0];
                if (is_space_token(first_next) || is_newline_token(first_next)) {
                    add_space = 0;
                }
            }

            if (add_space) {
                fprintf(file, " ");
            }
        }
    }

    fclose(file);
    return 0;
}
// ...existing code...

char* file_content_to_string(FileContent *fc) {
    char *result = malloc(MAX_BUFFER);
    result[0] = '\0';
    int pos = 0;

    for (int i = 0; i < fc->sentence_count; i++) {
        for (int j = 0; j < fc->sentences[i].word_count; j++) {
            int len = strlen(fc->sentences[i].words[j]);
            if (pos + len + 2 < MAX_BUFFER) {
                strcpy(result + pos, fc->sentences[i].words[j]);
                pos += len;

                if (j < fc->sentences[i].word_count - 1) {
                    const char *cur = fc->sentences[i].words[j];
                    const char *next = fc->sentences[i].words[j + 1];
                    int cur_is_delim = is_delimiter(cur[0]);
                    int next_is_delim = is_delimiter(next[0]);
                    int cur_is_newline = (cur[0] == '\n' && cur[1] == '\0');
                    int next_is_newline = (next[0] == '\n' && next[1] == '\0');
                    int cur_is_space = is_space_token(cur);
                    int next_is_space = is_space_token(next);

                    if (cur_is_space || next_is_space || cur_is_newline || next_is_newline) {
                        continue;
                    }

                    if (cur_is_delim || next_is_delim) {
                        continue;
                    }

                    result[pos++] = ' ';
                }
            }
        }
        if (i < fc->sentence_count - 1) {
            int add_space = 1;

            if (fc->sentences[i].word_count > 0) {
                char *last = fc->sentences[i].words[fc->sentences[i].word_count - 1];
                if (is_newline_token(last) || is_space_token(last)) {
                    add_space = 0;
                }
            }

            if (fc->sentences[i+1].word_count > 0) {
                char *first_next = fc->sentences[i+1].words[0];
                if (is_space_token(first_next) || is_newline_token(first_next)) {
                    add_space = 0;
                }
            }

            if (add_space && pos + 1 < MAX_BUFFER) {
                result[pos++] = ' ';
            }
        }
    }

    result[pos] = '\0';
    return result;
}
````

Why this fixes your symptom
- Previously we always wrote an extra inter-sentence space when the previous sentence didn't end with a space/newline token. If the next sentence started with its own leading space token (which can result from previous writes/merges), you ended up with two spaces. Each subsequent write could re-introduce another leading space token, causing the spaces to accumulate.
- By checking the first token of the next sentence we avoid adding the extra space when the next sentence already provides spacing. This prevents the multiplicative growth while preserving spacing when there's no explicit space token.

Notes / testing suggestions
- Build and test WRITE sequence you described and confirm the gap between "." and "hey" stays a single space.
- I limited the change to output (serialization) functions to minimize risk to parsing/merge logic. If you still see doubled spacing, we can also add a guard in insert_word_in_sentence to avoid inserting leading space tokens at the start of a sentence when the sentence already begins with a space token.

If you want, I can also prepare a small unit test that exercises parse -> insert -> write -> read cycle to validate the spacing stays stable.

