int write_file_content(const char *filepath, FileContent *fc) {
    FILE *file = fopen(filepath, "w");
    if (!file) return -1;

    for (int i = 0; i < fc->sentence_count; i++) {
        for (int j = 0; j < fc->sentences[i].word_count; j++) {
            const char *curr = fc->sentences[i].words[j];

            /* If this token is an explicit space-token, collapse any following
               consecutive space-tokens into a single space in output. This
               prevents growth of spaces across repeated inserts. */
            if (is_space_token(curr)) {
                /* write a single space (preserve behaviour of earlier code that
                   treated explicit space tokens as providing spacing) */
                fputc(' ', file);
                /* skip subsequent explicit space tokens */
                while (j + 1 < fc->sentences[i].word_count &&
                       is_space_token(fc->sentences[i].words[j + 1])) {
                    j++;
