                if (next_is_space || next_is_newline) {
                    continue;
                }
                if (cur_is_delim || next_is_delim) {
                    continue;
                }

                if (pos + 1 < MAX_BUFFER) result[pos++] = ' ';
            }
        }

        if (i < fc->sentence_count - 1) {
            int add_space = 1;

            if (fc->sentences[i].word_count > 0) {
